"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["7267"],{84298(e){e.exports=JSON.parse('{"id":"FIN-1491","slug":"interpolation","term":"Interpolation","also_known_as":[],"difficulty":"Advanced","definition":"Interpolation is a method of estimating an unknown value that lies between two or more known values.","explanation":["When data are available only at certain points, interpolation fills in the gaps. The simplest form, linear interpolation, assumes the value changes in a straight line between known points.","For example, if the two-year interest rate is 4% and the five-year rate is 5%, a linear interpolation estimates the three-year rate as about 4.33%, a third of the way between them, since three years is one third of the distance from two to five.","Interpolation is widely used in finance. Analysts interpolate yield curves to find rates for maturities that are not directly quoted, estimate values between data points in tables and fill in missing data in time series.","More sophisticated methods, such as cubic splines, fit smooth curves through the known points, which can be more realistic for yield curves. Interpolation is generally more reliable than extrapolation, because it stays within the range of known data, but it still assumes the pattern between points is smooth and predictable."],"note":"","total":1500,"prev":{"slug":"international-monetary-fund","term":"International Monetary Fund (IMF)"},"next":{"slug":"intrinsic-value","term":"Intrinsic Value"}}')}}]);